-- Stock lots retain the exact approved payable allocation and its recorded tax.
CREATE TABLE tt_stock_lots(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES tt_properties(id),bill_id TEXT NOT NULL REFERENCES tt_bills(id),bill_version INTEGER NOT NULL,name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),day TEXT NOT NULL,reference TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(bill_id,bill_version,property_id));
CREATE TABLE tt_stock_uses(id TEXT PRIMARY KEY,lot_id TEXT NOT NULL REFERENCES tt_stock_lots(id),job_id TEXT NOT NULL,tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id),job_version INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),day TEXT NOT NULL,reference TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
DROP VIEW tt_gl_chart;
CREATE VIEW tt_gl_chart AS SELECT column1 AS code,column2 AS name,column3 AS kind,column4 AS fund,column5 AS cash,column6 AS created_by,column7 AS created_at FROM (VALUES ('inventory','Maintenance stock','asset','operating',0,'migration','2026-10-25'),('cash','Recorded external cash','asset','both',1,'migration','2026-10-22'),('receivable','Lease receivable','asset','operating',0,'migration','2026-10-22'),('lease_income','Lease income','income','operating',0,'migration','2026-10-22'),('deposit_liability','Resident security deposits','liability','deposit',0,'migration','2026-10-22'),('expense','Property expenses','expense','operating',0,'migration','2026-10-22'),('payable','Vendor payables','liability','operating',0,'migration','2026-10-22'),('fee_expense','Management expenses including recorded fee tax','expense','operating',0,'migration','2026-10-22'),('fee_payable','Management fee payables','liability','operating',0,'migration','2026-10-22'),('tax_payable','Lease tax payable','liability','operating',0,'migration','2026-10-22'),('contribution','Owner contributions','equity','operating',0,'migration','2026-10-22'),('opening_equity','Opening balance equity','equity','both',0,'migration','2026-10-22')) UNION ALL SELECT * FROM tt_gl_accounts;
INSERT INTO tt_role_actions(role,action) SELECT role,'stock.receive' FROM tt_role_actions WHERE action='bill.approve';
INSERT INTO tt_role_actions(role,action) SELECT role,'stock.consume' FROM tt_role_actions WHERE action='maintenance.approve';
CREATE TRIGGER tt_stock_bill_frozen BEFORE UPDATE OF version,state,vendor_id,day ON tt_bills WHEN EXISTS(SELECT 1 FROM tt_stock_lots WHERE bill_id=OLD.id) BEGIN SELECT RAISE(ABORT,'CHECK constraint: stock source payable is frozen'); END;
CREATE TRIGGER tt_stock_quantity BEFORE INSERT ON tt_stock_uses WHEN NEW.quantity+COALESCE((SELECT SUM(quantity) FROM tt_stock_uses WHERE lot_id=NEW.lot_id),0)>(SELECT quantity FROM tt_stock_lots WHERE id=NEW.lot_id) BEGIN SELECT RAISE(ABORT,'CHECK constraint: insufficient stock'); END;
CREATE TRIGGER tt_stock_lot_kept BEFORE DELETE ON tt_stock_lots BEGIN SELECT RAISE(ABORT,'Stock accounting is retained'); END;
CREATE TRIGGER tt_stock_lot_fixed BEFORE UPDATE ON tt_stock_lots WHEN NOT(NEW.id=OLD.id AND NEW.property_id=OLD.property_id AND NEW.bill_id=OLD.bill_id AND NEW.bill_version=OLD.bill_version AND NEW.name='Retained stock' AND NEW.reference=OLD.id AND NEW.quantity=OLD.quantity AND NEW.amount_cents=OLD.amount_cents AND NEW.day=OLD.day AND NEW.recorded_by=OLD.recorded_by AND NEW.recorded_at=OLD.recorded_at AND EXISTS(SELECT 1 FROM tt_bill_subjects s JOIN tt_erasure_work w ON w.tenancy_id=s.tenancy_id WHERE s.kind='bill' AND s.entity_id=OLD.bill_id)) BEGIN SELECT RAISE(ABORT,'Stock accounting is immutable'); END;
CREATE TRIGGER tt_stock_use_kept BEFORE DELETE ON tt_stock_uses BEGIN SELECT RAISE(ABORT,'Stock accounting is retained'); END;
CREATE TRIGGER tt_stock_use_fixed BEFORE UPDATE ON tt_stock_uses WHEN NOT(NEW.id=OLD.id AND NEW.lot_id=OLD.lot_id AND NEW.job_id=OLD.job_id AND NEW.tenancy_id=OLD.tenancy_id AND NEW.job_version=OLD.job_version AND NEW.quantity=OLD.quantity AND NEW.amount_cents=OLD.amount_cents AND NEW.day=OLD.day AND NEW.reference=OLD.id AND NEW.recorded_by=OLD.recorded_by AND NEW.recorded_at=OLD.recorded_at AND EXISTS(SELECT 1 FROM tt_erasure_work WHERE tenancy_id=OLD.tenancy_id)) BEGIN SELECT RAISE(ABORT,'Stock accounting is immutable'); END;
CREATE TRIGGER tt_stock_clock_receipt AFTER INSERT ON tt_stock_lots BEGIN UPDATE tt_budget_clock SET version=version+1; END;
CREATE TRIGGER tt_stock_clock_use AFTER INSERT ON tt_stock_uses BEGIN UPDATE tt_budget_clock SET version=version+1; END;
